import{_ as t,c as o,o as s,ae as a}from"./chunks/framework.CliRSA9F.js";const g=JSON.parse('{"title":"YouTube Insights","description":"","frontmatter":{},"headers":[],"relativePath":"features/youtube-insights.md","filePath":"features/youtube-insights.md"}'),n={name:"features/youtube-insights.md"};function r(i,e,h,l,d,u){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="youtube-insights" tabindex="-1">YouTube Insights <a class="header-anchor" href="#youtube-insights" aria-label="Permalink to &quot;YouTube Insights&quot;">​</a></h1><h2 id="see-how-viewers-find-your-podcast-on-youtube" tabindex="-1">See How Viewers Find Your Podcast on YouTube <a class="header-anchor" href="#see-how-viewers-find-your-podcast-on-youtube" aria-label="Permalink to &quot;See How Viewers Find Your Podcast on YouTube&quot;">​</a></h2><p>YouTube Insights connects your podcast&#39;s YouTube channel to PodSEO so you can see how people actually find your videos: the real searches that bring viewers in, where your views come from, and how each episode&#39;s video performs. It then compares those searches with the keywords you already track and suggests specific, keyword-based changes to your video titles.</p><p>Most podcast analytics stop at the listening apps. If you publish full episodes or clips on YouTube, a large part of your discovery happens in YouTube search and recommendations, and YouTube&#39;s own reports don&#39;t tell you which of those searches match your podcast keyword strategy. YouTube Insights brings both views together on one page.</p><p><strong>To access</strong>: Click <strong>YouTube</strong> in the sidebar (it sits between Social Publishing and PR &amp; Media Coverage and carries a <strong>Beta</strong> label). The page title is <strong>YouTube Insights</strong>.</p><h2 id="getting-started-connect-and-activate" tabindex="-1"><strong>Getting Started: Connect and Activate</strong> <a class="header-anchor" href="#getting-started-connect-and-activate" aria-label="Permalink to &quot;**Getting Started: Connect and Activate**&quot;">​</a></h2><p>YouTube Insights uses the same YouTube connection as <a href="/features/social-publishing.html">Social Publishing</a>. Setting it up takes two steps: connect the channel, then activate Insights.</p><h3 id="step-1-connect-your-youtube-channel" tabindex="-1"><strong>Step 1: Connect your YouTube channel</strong> <a class="header-anchor" href="#step-1-connect-your-youtube-channel" aria-label="Permalink to &quot;**Step 1: Connect your YouTube channel**&quot;">​</a></h3><p>If no channel is connected yet, the page shows <strong>Connect the YouTube channel of &quot;[your podcast]&quot;</strong> with a <strong>Connect YouTube</strong> button.</p><ol><li>Click <strong>Connect YouTube</strong>.</li><li>Google shows its account chooser. <strong>Pick the Google account (or Brand Account) that owns your podcast&#39;s YouTube channel.</strong> If you&#39;re signed in to several Google accounts, take a moment here: the account you choose is the channel PodSEO connects.</li><li>Approve the permissions Google asks for. They let PodSEO read your channel&#39;s statistics and, if you choose to use it later, publish Shorts from Social Publishing.</li><li>You return to PodSEO with a confirmation such as &quot;Connected [channel name].&quot;</li></ol><p>If your channel is already connected for Social Publishing, you can skip this step: there is no need to sign in again.</p><h3 id="step-2-activate-insights" tabindex="-1"><strong>Step 2: Activate Insights</strong> <a class="header-anchor" href="#step-2-activate-insights" aria-label="Permalink to &quot;**Step 2: Activate Insights**&quot;">​</a></h3><p>Connecting a channel doesn&#39;t start reading its analytics on its own. Open the <strong>YouTube</strong> page and you&#39;ll see <strong>Your channel &quot;[channel name]&quot; is already connected</strong>. Click <strong>Activate Insights</strong>.</p><p>PodSEO then imports your channel, starting with the last six months of data. This usually takes a few minutes, and the page shows <strong>Importing your channel</strong> while it works. Come back a little later and your insights will be ready. After that, PodSEO refreshes your channel&#39;s data every day.</p><p>The <a href="/features/command-center.html">Command Center</a> also reminds you with an <strong>Activate YouTube Insights</strong> task when a channel is connected but Insights isn&#39;t active yet.</p><p><strong>Read-only by design.</strong> YouTube Insights only reads data. PodSEO never edits your videos, titles, or channel settings: every change is something you make yourself in YouTube Studio.</p><h2 id="what-you-ll-see" tabindex="-1"><strong>What You&#39;ll See</strong> <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;**What You&#39;ll See**&quot;">​</a></h2><h3 id="channel-header" tabindex="-1"><strong>Channel header</strong> <a class="header-anchor" href="#channel-header" aria-label="Permalink to &quot;**Channel header**&quot;">​</a></h3><p>The top of the page shows your channel&#39;s name and picture, subscriber count, number of videos, and when the data was last updated. Admins also see a <strong>Manage channel</strong> link, which opens Social Publishing where the connection is managed. The <strong>How it works</strong> button opens a short explanation of the page.</p><p>If a few video matches are waiting for your review, a banner tells you how many need confirmation, with a <strong>Review matches</strong> button that jumps to the episode list.</p><h3 id="channel-performance" tabindex="-1"><strong>Channel performance</strong> <a class="header-anchor" href="#channel-performance" aria-label="Permalink to &quot;**Channel performance**&quot;">​</a></h3><p>Choose a time range with the <strong>7 days</strong>, <strong>28 days</strong>, and <strong>90 days</strong> tabs. For the selected period you&#39;ll see:</p><ul><li><strong>Views</strong>: total views on your channel</li><li><strong>Watch hours</strong>: total time viewers spent watching</li><li><strong>Subscribers</strong>: the net change (subscribers gained minus subscribers lost)</li><li><strong>Views from YouTube search</strong>: the share of views that came from people searching on YouTube, with the number of views behind it</li></ul><p>Each figure is compared with the previous period of the same length (for example &quot;vs previous 28 days&quot;). When there isn&#39;t enough history yet, you&#39;ll see &quot;Not enough history to compare yet.&quot; If YouTube hasn&#39;t reported every day of the period, a note under the figures says how many days are covered, and the comparison uses per-day averages so missing days don&#39;t distort it.</p><p>The numbers come from YouTube Analytics. YouTube finalizes its figures with a delay of about two days, so the most recent day or two may not be included yet.</p><h3 id="where-your-views-come-from" tabindex="-1"><strong>Where your views come from</strong> <a class="header-anchor" href="#where-your-views-come-from" aria-label="Permalink to &quot;**Where your views come from**&quot;">​</a></h3><p>This breakdown shows the main traffic sources for the selected period, such as <strong>YouTube search</strong>, <strong>Suggested videos</strong>, <strong>Browse features</strong>, <strong>Shorts feed</strong>, <strong>External</strong>, <strong>Channel pages</strong>, and <strong>Playlists</strong>, with the share of views each one brought. YouTube search is highlighted because it&#39;s the source you can influence most directly with keywords. Smaller sources are grouped under <strong>Other</strong>.</p><h3 id="how-viewers-find-you" tabindex="-1"><strong>How viewers find you</strong> <a class="header-anchor" href="#how-viewers-find-you" aria-label="Permalink to &quot;**How viewers find you**&quot;">​</a></h3><p>This section has two tabs:</p><p><strong>YouTube searches</strong> lists the actual search terms that brought viewers to your videos in the last 28 days, with the views each one produced. A summary line tells you how many real searches brought viewers in. Two badges help you read the list:</p><ul><li><strong>Tracked</strong>: the search matches one of the keywords you track in PodSEO</li><li><strong>Show name</strong>: the viewer searched for your show by name. These viewers already know you, so they&#39;re shown in a lighter style: the other searches are the ones that reveal how <em>new</em> viewers discover you</li></ul><p><strong>Tracked keywords</strong> shows your tracked podcast keywords and how many YouTube views came from searches that exactly match each one over the last 28 days. A link at the bottom takes you to the full <a href="/features/keyword-tracker.html">Keyword Tracker</a>.</p><p>Comparing the two tabs is where the value lies: searches that bring viewers but aren&#39;t in your keyword strategy are candidates to add, and tracked keywords that bring no YouTube views show where your videos aren&#39;t being found yet.</p><h3 id="episode-insights" tabindex="-1"><strong>Episode insights</strong> <a class="header-anchor" href="#episode-insights" aria-label="Permalink to &quot;**Episode insights**&quot;">​</a></h3><p>The episode list shows your most recent podcast episodes alongside their YouTube videos, with views over the last 28 days. For each episode you&#39;ll see:</p><ul><li><strong>Video</strong>: whether the episode has a matching YouTube video. <strong>Matched</strong> means the video is linked; <strong>Needs confirmation</strong> means PodSEO found a likely match and wants you to check it; <strong>Not on YouTube</strong> means no video of your channel is linked yet. If you&#39;ve published Shorts from that episode, their count appears here too.</li><li><strong>Views 28d</strong>: views of the episode&#39;s video in the last 28 days</li><li><strong>From search</strong>: the share of those views that came from YouTube search</li><li><strong>Next action</strong>: what to do next for that episode, such as <strong>Confirm match</strong> or reviewing a title suggestion</li></ul><p>Click an episode title (or its action button) to open the episode&#39;s detail window.</p><h2 id="matching-videos-to-episodes" tabindex="-1"><strong>Matching Videos to Episodes</strong> <a class="header-anchor" href="#matching-videos-to-episodes" aria-label="Permalink to &quot;**Matching Videos to Episodes**&quot;">​</a></h2><p>PodSEO automatically pairs your YouTube videos with your podcast episodes by comparing titles, episode numbers, and publish dates. Strong matches are linked straight away; less certain ones are marked <strong>Needs confirmation</strong> so you can decide. Shorts are treated as clips and are never matched automatically as a full episode.</p><p>In the episode window, under <strong>YouTube video</strong>:</p><ul><li><strong>Confirm match</strong> links the suggested video to the episode, so its numbers and title suggestions apply to that episode.</li><li><strong>Not this episode</strong> tells PodSEO the suggestion is wrong. That video won&#39;t be suggested for this episode again.</li><li><strong>Choose a video to link</strong> (or <strong>Choose a different video</strong>) lists your channel&#39;s recent videos so you can link the right one yourself when PodSEO didn&#39;t find it.</li></ul><p>Your decisions are kept: PodSEO never overrides a match you confirmed or rejected.</p><h2 id="the-episode-window" tabindex="-1"><strong>The Episode Window</strong> <a class="header-anchor" href="#the-episode-window" aria-label="Permalink to &quot;**The Episode Window**&quot;">​</a></h2><p>Besides the video match, each episode&#39;s window shows:</p><h3 id="performance-across-platforms" tabindex="-1"><strong>Performance across platforms</strong> <a class="header-anchor" href="#performance-across-platforms" aria-label="Permalink to &quot;**Performance across platforms**&quot;">​</a></h3><p>Side-by-side tiles show how the same episode is doing on each platform:</p><ul><li><strong>YouTube views</strong> for the last 28 days, the share from search, and the average view duration</li><li><strong>Apple episode rank</strong>: the best position the episode holds on Apple Podcasts for one of your tracked keywords (top 20), with the keyword</li><li><strong>Spotify show rank</strong>: your show&#39;s current position on Spotify for that same keyword, shown when a recent rank is available</li></ul><p>The figures are shown separately and never added together, because each platform measures something different. If the video match still needs confirmation, the section is marked &quot;provisional match.&quot;</p><h3 id="title-suggestions" tabindex="-1"><strong>Title suggestions</strong> <a class="header-anchor" href="#title-suggestions" aria-label="Permalink to &quot;**Title suggestions**&quot;">​</a></h3><p>Once a video is matched, PodSEO checks whether its YouTube title is missing a keyword the episode already performs well for. The suggestion looks like <strong>Put &quot;[keyword]&quot; in the video title</strong>, and explains why: for example, the episode ranks #4 on Apple Podcasts for that keyword, and real YouTube searches on your channel contain it. You&#39;ll see:</p><ul><li><strong>Current title</strong>: the title on YouTube today</li><li><strong>Example</strong>: your current title with the keyword added, as a starting point. If the example is longer than YouTube&#39;s 100-character title limit, a note reminds you to shorten it.</li><li><strong>Copy suggested title</strong>: copies the example so you can paste it into YouTube Studio</li><li><strong>Mark as applied</strong>: records that you&#39;ve made the change, so the suggestion shows as <strong>Applied</strong> with the date</li></ul><p>If the title already contains every word of the keyword but not the exact phrase people search, PodSEO tells you which words are there and suggests reworking the title so the phrase appears as written.</p><p>When there&#39;s nothing to suggest, the window says so: either the title already includes the tracked keyword the episode ranks best for, or the episode isn&#39;t in Apple&#39;s top 20 for any tracked keyword yet.</p><p>Suggestions only appear for confirmed matches (or very confident automatic ones), so you&#39;re never told to rename the wrong video. Open suggestions also appear as tasks in the <a href="/features/command-center.html">Command Center</a> (up to two at a time); clicking one opens that episode&#39;s window directly.</p><h2 id="when-there-isn-t-much-data-yet" tabindex="-1"><strong>When There Isn&#39;t Much Data Yet</strong> <a class="header-anchor" href="#when-there-isn-t-much-data-yet" aria-label="Permalink to &quot;**When There Isn&#39;t Much Data Yet**&quot;">​</a></h2><p>If your channel had fewer than about 100 views in the last 90 days, you&#39;ll see <strong>Not much data from your channel yet</strong>. YouTube doesn&#39;t report search terms or traffic sources for very small channels, so those sections stay empty until your audience grows. You can still match videos to episodes and use the title suggestions in the meantime.</p><p>Similarly, <strong>No searches reported yet</strong> simply means YouTube hasn&#39;t listed any search terms for your videos so far. It appears once enough viewers find you through search.</p><h2 id="keeping-the-connection-working" tabindex="-1"><strong>Keeping the Connection Working</strong> <a class="header-anchor" href="#keeping-the-connection-working" aria-label="Permalink to &quot;**Keeping the Connection Working**&quot;">​</a></h2><p>Google connections can stop working, for example if you remove PodSEO&#39;s access in your Google account settings or Google expires the authorization. When that happens, the page shows <strong>Reconnect YouTube to keep your insights up to date</strong> with a <strong>Reconnect YouTube</strong> button. Until you reconnect, PodSEO stops reading the channel and the page shows the numbers from the last successful update.</p><p><strong>Your YouTube data is deleted if the connection stays broken.</strong> Following YouTube&#39;s data policies, PodSEO deletes a channel&#39;s YouTube data 30 days after the connection stops working, and right away if you disconnect the YouTube account in Social Publishing (unless the same channel is still connected to another of your podcasts). If the data was deleted, connecting the channel again and clicking <strong>Activate Insights</strong> starts a fresh import.</p><h2 id="who-can-do-what" tabindex="-1"><strong>Who Can Do What</strong> <a class="header-anchor" href="#who-can-do-what" aria-label="Permalink to &quot;**Who Can Do What**&quot;">​</a></h2><p>In an organization, only <strong>Admins</strong> and <strong>Owners</strong> can connect or reconnect the channel, activate Insights, confirm or reject video matches, link videos, and mark suggestions as applied. Other team members can view the page and open each episode&#39;s window; where an action is needed they&#39;ll see a note asking an account admin to do it. In a personal account, you can do everything.</p><p>YouTube Insights isn&#39;t available for draft podcasts that don&#39;t have a feed yet.</p><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><ul><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong>: YouTube searches that bring viewers but aren&#39;t tracked are good candidates for your Secondary keywords. The title suggestions are built from your tracked keywords, so a focused strategy means better suggestions.</li><li><strong><a href="/features/keyword-tracker.html">Keyword Tracker</a></strong>: with a channel linked to your podcast, the tracker can also show where your channel ranks in <strong>YouTube</strong> search (youtube.com) for your tracked keywords, separately from YouTube Music.</li><li><strong><a href="/features/episode-rankings.html">Episode Rankings</a></strong>: the Apple episode ranks in the episode window are the same data, used here to find keywords your YouTube titles are missing.</li><li><strong><a href="/features/social-publishing.html">Social Publishing</a></strong>: the same YouTube connection lets you publish Shorts made from your episodes.</li><li><strong><a href="/features/command-center.html">Command Center</a></strong>: activation reminders and open title suggestions appear as tasks.</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>YouTube Insights is available on every plan.</p><ul><li><strong>Free</strong>: channel performance (views, watch hours, subscribers, search share, traffic sources), one reported search term, and insights for your <strong>latest episode</strong>, including its video match and title suggestion.</li><li><strong>Paid plans</strong>: every reported search term and insights across your recent episodes (the 20 most recent are listed), with a title suggestion for each matched episode.</li></ul><p>On the free plan, older episodes and additional search terms are counted in the list (for example &quot;3 more episodes available with a paid plan&quot;) with a <strong>Compare access</strong> link. Suggestions always depend on the data available and on confirmed matches.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Before you click <strong>Connect YouTube</strong>, check which Google account owns the channel. Choosing the wrong account is the most common reason a connection fails.</li><li>Review <strong>Needs confirmation</strong> matches first: until an episode&#39;s video is matched, it can&#39;t get title suggestions.</li><li>Read the YouTube searches list with your keyword strategy open. Searches that bring viewers but aren&#39;t tracked are free keyword research from your real audience.</li><li>Look at the <strong>Views from YouTube search</strong> figure over time. If it grows after you apply title suggestions, your keyword work is paying off on YouTube too.</li><li>Use <strong>Mark as applied</strong> so you can keep track of what you&#39;ve already changed, and focus on the suggestions that are still open.</li></ul>',72)])])}const p=t(n,[["render",r]]);export{g as __pageData,p as default};
